// WeeklyIntentCache 意图识别结果缓存
// 按用户提问的 MD5 哈希缓存意图识别结果，减少重复 LLM 调用
type WeeklyIntentCache struct {
	mu      sync.RWMutex
	items   map[string]IntentCacheEntry
	ttl     time.Duration
	maxSize int
}

// NewWeeklyIntentCache 创建新的意图缓存
func NewWeeklyIntentCache() *WeeklyIntentCache {
	cache := &WeeklyIntentCache{
		items:   make(map[string]IntentCacheEntry),
		ttl:     30 * time.Minute,
		maxSize: 500,
	}
	// 启动后台清理协程
	go cache.cleanupLoop()
	return cache
}

// makeCacheKey 生成缓存 key：对规范化后的用户提问计算 MD5
func makeCacheKey(userPrompt string) string {
	normalized := strings.TrimSpace(strings.ToLower(userPrompt))
	hash := md5.Sum([]byte(normalized))
	return hex.EncodeToString(hash[:])
}

// Get 从缓存获取意图识别结果
// 返回: 结果, tool_calls, 是否使用了 Fallback, 是否命中
func (c *WeeklyIntentCache) Get(userPrompt string) (WeeklyIntentRecognitionResult, []WeeklyToolCall, bool, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	key := makeCacheKey(userPrompt)
	entry, ok := c.items[key]
	if !ok {
		return WeeklyIntentRecognitionResult{}, nil, false, false
	}
	// 检查是否过期
	if time.Since(entry.CreatedAt) > c.ttl {
		return WeeklyIntentRecognitionResult{}, nil, false, false
	}
	return entry.Intent, entry.ToolCalls, entry.UsedFallback, true
}

// Set 将意图识别结果写入缓存
func (c *WeeklyIntentCache) Set(userPrompt string, intent WeeklyIntentRecognitionResult, toolCalls []WeeklyToolCall, usedFallback bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	// 简单淘汰：超过上限时清空一半（避免复杂 LRU）
	if len(c.items) >= c.maxSize {
		c.evictHalf()
	}

	key := makeCacheKey(userPrompt)
	c.items[key] = IntentCacheEntry{
		Intent:       intent,
		ToolCalls:    toolCalls,
		UsedFallback: usedFallback,
		CreatedAt:    time.Now(),
	}
}

// evictHalf 淘汰一半最旧的缓存条目
func (c *WeeklyIntentCache) evictHalf() {
	type kv struct {
		key   string
		entry IntentCacheEntry
	}
	entries := make([]kv, 0, len(c.items))
	for k, v := range c.items {
		entries = append(entries, kv{key: k, entry: v})
	}
	// 按时间升序排序
	for i := 0; i < len(entries)-1; i++ {
		for j := i + 1; j < len(entries); j++ {
			if entries[i].entry.CreatedAt.After(entries[j].entry.CreatedAt) {
				entries[i], entries[j] = entries[j], entries[i]
			}
		}
	}
	// 删除前一半
	for i := 0; i < len(entries)/2; i++ {
		delete(c.items, entries[i].key)
	}
}

// cleanupLoop 定期清理过期缓存（每 10 分钟执行一次）
func (c *WeeklyIntentCache) cleanupLoop() {
	ticker := time.NewTicker(10 * time.Minute)
	defer ticker.Stop()
	for range ticker.C {
		c.cleanup()
	}
}

// cleanup 删除所有过期条目
func (c *WeeklyIntentCache) cleanup() {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	for key, entry := range c.items {
		if now.Sub(entry.CreatedAt) > c.ttl {
			delete(c.items, key)
		}
	}
}

